{"file_text": "using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe { Id = 1, Title = "Classic Pancakes", Category = "breakfast", Ingredients = "2 cups flour\n2 eggs\n1 cup milk\n2 tbsp sugar\n1 tsp baking powder\nPinch of salt", Steps = "1. Mix dry ingredients in a bowl.\n2. Whisk eggs and milk together.\n3. Combine wet and dry ingredients until just mixed.\n4. Heat a skillet over medium heat and grease lightly.\n5. Pour batter and cook until bubbles form, then flip.\n6. Serve with maple syrup and fresh berries.", AverageRating = 4.5, RatingCount = 12 },
        new Recipe { Id = 2, Title = "Avocado Toast", Category = "breakfast", Ingredients = "2 slices sourdough bread\n1 ripe avocado\n1 tbsp lemon juice\nSalt and pepper\nRed pepper flakes\nEverything bagel seasoning", Steps = "1. Toast the bread until golden and crispy.\n2. Mash avocado with lemon juice, salt, and pepper.\n3. Spread avocado mixture on toast.\n4. Sprinkle with red pepper flakes and everything bagel seasoning.\n5. Optional: top with a fried egg.", AverageRating = 4.2, RatingCount = 8 },
        new Recipe { Id = 3, Title = "Caesar Salad", Category = "lunch", Ingredients = "1 head romaine lettuce\n1/2 cup croutons\n1/4 cup parmesan cheese\n3 tbsp Caesar dressing\n1 grilled chicken breast\nBlack pepper", Steps = "1. Wash and chop romaine lettuce.\n2. Slice grilled chicken breast.\n3. Toss lettuce with Caesar dressing.\n4. Top with croutons, parmesan, and chicken.\n5. Finish with freshly cracked black pepper.", AverageRating = 4.0, RatingCount = 6 },
        new Recipe { Id = 4, Title = "Turkey Club Sandwich", Category = "lunch", Ingredients = "3 slices bread (toasted)\nSliced turkey\nBacon strips\nLettuce\nTomato slices\nMayonnaise", Steps = "1. Toast bread slices until golden.\n2. Cook bacon until crispy.\n3. Spread mayo on each bread slice.\n4. Layer turkey, bacon, lettuce, and tomato.\n5. Stack with middle bread slice and repeat layers.\n6. Cut diagonally and secure with toothpicks.", AverageRating = 4.3, RatingCount = 10 },
        new Recipe { Id = 5, Title = "Spaghetti Bolognese", Category = "dinner", Ingredients = "400g spaghetti\n500g ground beef\n1 can crushed tomatoes\n1 onion (diced)\n3 cloves garlic\n2 tbsp olive oil\nFresh basil\nParmesan cheese", Steps = "1. Cook spaghetti according to package directions.\n2. Sauté onion and garlic in olive oil.\n3. Add ground beef and cook until browned.\n4. Pour in crushed tomatoes and simmer 20 minutes.\n5. Season with salt, pepper, and Italian herbs.\n6. Serve sauce over pasta with fresh basil and parmesan.", AverageRating = 4.8, RatingCount = 20 },
        new Recipe { Id = 6, Title = "Grilled Salmon", Category = "dinner", Ingredients = "4 salmon fillets\n2 tbsp olive oil\n1 lemon\n2 cloves garlic (minced)\nFresh dill\nSalt and pepper", Steps = "1. Preheat grill to medium-high heat.\n2. Brush salmon with olive oil and season with salt, pepper, and garlic.\n3. Grill skin-side down for 4-5 minutes.\n4. Flip carefully and cook another 3-4 minutes.\n5. Squeeze lemon over the top and garnish with fresh dill.\n6. Serve with roasted vegetables.", AverageRating = 4.6, RatingCount = 15 },
        new Recipe { Id = 7, Title = "Chocolate Lava Cake", Category = "desserts", Ingredients = "200g dark chocolate\n100g butter\n2 eggs\n2 egg yolks\n1/4 cup sugar\n2 tbsp flour\nButter for ramekins", Steps = "1. Preheat oven to 425°F (220°C).\n2. Melt chocolate and butter together.\n3. Whisk eggs, yolks, and sugar until thick.\n4. Fold chocolate mixture into egg mixture.\n5. Add flour and mix gently.\n6. Pour into buttered ramekins.\n7. Bake 12-14 minutes until edges are set but center is soft.\n8. Invert onto plates and serve immediately.", AverageRating = 4.9, RatingCount = 25 },
        new Recipe { Id = 8, Title = "Tiramisu", Category = "desserts", Ingredients = "6 egg yolks\n3/4 cup sugar\n500g mascarpone cheese\n2 cups heavy cream\n2 cups strong espresso (cooled)\nLadyfinger biscuits\nCocoa powder", Steps = "1. Whisk egg yolks and sugar until pale and thick.\n2. Add mascarpone and mix until smooth.\n3. Whip heavy cream to stiff peaks and fold into mascarpone mixture.\n4. Dip ladyfingers briefly in espresso.\n5. Layer soaked ladyfingers in a dish.\n6. Spread mascarpone mixture over ladyfingers.\n7. Repeat layers and refrigerate 4+ hours.\n8. Dust with cocoa powder before serving.", AverageRating = 4.7, RatingCount = 18 },
    };

    public List<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetRecipeById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public List<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().ToList();
    }

    public void AddRecipe(RecipeSubmission submission)
    {
        var newId = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(new Recipe
        {
            Id = newId,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients,
            Steps = submission.Steps,
            AverageRating = 0,
            RatingCount = 0
        });
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is not null && stars >= 1 && stars <= 5)
        {
            var totalStars = recipe.AverageRating * recipe.RatingCount;
            recipe.RatingCount++;
            recipe.AverageRating = (totalStars + stars) / recipe.RatingCount;
        }
    }
}
