@page "/recipes/{Category}"
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<PageTitle>@CategoryDisplay Recipes - Recipe Community</PageTitle>

<h1>@CategoryDisplay Recipes</h1>

@if (Recipes.Count == 0)
{
    <p>No recipes found in this category.</p>
}
else
{
    <div class="row">
        @foreach (var recipe in Recipes)
        {
            <div class="col-md-6 mb-4">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted">
                            ⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)
                        </p>
                        <a href="recipes/@Category/@recipe.Id" class="btn btn-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter]
    public string Category { get; set; } = string.Empty;

    private List<RecipeCommunity.Models.Recipe> Recipes { get; set; } = new();
    private string CategoryDisplay => System.Globalization.CultureInfo.CurrentCulture.TextInfo.ToTitleCase(Category);

    protected override void OnParametersSet()
    {
        Recipes = RecipeService.GetRecipesByCategory(Category);
    }
}

@page "/recipes/{Category}/{Id:int}"
@using RecipeCommunity.Services
@inject RecipeService RecipeService

@if (Recipe is null)
{
    <PageTitle>Recipe Not Found</PageTitle>
    <h1>Recipe Not Found</h1>
    <p>The recipe you're looking for doesn't exist.</p>
}
else
{
    <PageTitle>@Recipe.Title - Recipe Community</PageTitle>

    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="recipes/@Category">@CategoryDisplay</a></li>
            <li class="breadcrumb-item active">@Recipe.Title</li>
        </ol>
    </nav>

    <h1>@Recipe.Title</h1>

    <div class="mb-4">
        <StarRating RecipeId="@Recipe.Id" @rendermode="InteractiveServer" />
    </div>

    <div class="row">
        <div class="col-md-4">
            <div class="card mb-4">
                <div class="card-header"><h5 class="mb-0">🧾 Ingredients</h5></div>
                <div class="card-body">
                    <ul class="list-unstyled">
                        @foreach (var ingredient in Recipe.Ingredients.Split('\n'))
                        {
                            <li class="mb-1">• @ingredient</li>
                        }
                    </ul>
                </div>
            </div>
        </div>
        <div class="col-md-8">
            <div class="card">
                <div class="card-header"><h5 class="mb-0">📝 Instructions</h5></div>
                <div class="card-body">
                    @foreach (var step in Recipe.Steps.Split('\n'))
                    {
                        <p>@step</p>
                    }
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter]
    public string Category { get; set; } = string.Empty;

    [Parameter]
    public int Id { get; set; }

    private RecipeCommunity.Models.Recipe? Recipe { get; set; }
    private string CategoryDisplay => System.Globalization.CultureInfo.CurrentCulture.TextInfo.ToTitleCase(Category);

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetRecipeById(Id);
    }
}

@using RecipeCommunity.Services
