+        <button class="btn btn-link p-0 fs-4 text-decoration-none"
+                @onclick="() => Rate(star)"
+                title="Rate @star stars">
+            @(star <= SelectedRating ? "★" : "☆")
+        </button>
+    }
+    @if (SelectedRating > 0)
+    {
+        <span class="ms-2 text-muted">You rated @SelectedRating/5</span>
+    }
+</div>
+
+@code {
+    [Parameter]
+    public int RecipeId { get; set; }
+
+    private int SelectedRating { get; set; }
+
+    private void Rate(int stars)
+    {
+        SelectedRating = stars;
+        RecipeService.AddRating(RecipeId, stars);
+    }
