@page "/submit"
@using RecipeCommunity.Models
@using RecipeCommunity.Services
@inject RecipeService RecipeService
@rendermode InteractiveServer

<PageTitle>Submit a Recipe - Recipe Community</PageTitle>

<h1>📝 Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (Submitted)
{
    <div class="alert alert-success">
        <h4>✅ Recipe Submitted!</h4>
        <p>Thank you for sharing "<strong>@Submission.Title</strong>" with the community.</p>
        <button class="btn btn-primary" @onclick="Reset">Submit Another</button>
    </div>
}
else
{
    <div class="card">
        <div class="card-body">
            <EditForm Model="@Submission" OnValidSubmit="HandleSubmit" FormName="recipeForm">
                <div class="mb-3">
                    <label class="form-label" for="title">Recipe Title</label>
                    <InputText id="title" class="form-control" @bind-Value="Submission.Title" placeholder="e.g., Grandma's Apple Pie" />
                </div>

                <div class="mb-3">
                    <label class="form-label" for="category">Category</label>
                    <InputSelect id="category" class="form-select" @bind-Value="Submission.Category">
                        <option value="">-- Select a category --</option>
                        <option value="breakfast">Breakfast</option>
                        <option value="lunch">Lunch</option>
                        <option value="dinner">Dinner</option>
                        <option value="desserts">Desserts</option>
                    </InputSelect>
                </div>

                <div class="mb-3">
                    <label class="form-label" for="ingredients">Ingredients</label>
                    <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="Submission.Ingredients" placeholder="One ingredient per line" />
                </div>

                <div class="mb-3">
                    <label class="form-label" for="steps">Steps</label>
                    <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="Submission.Steps" placeholder="Step-by-step instructions" />
                </div>

                <button type="submit" class="btn btn-success"
                        disabled="@(string.IsNullOrWhiteSpace(Submission.Title) || string.IsNullOrWhiteSpace(Submission.Category))">
                    Submit Recipe
                </button>
            </EditForm>
        </div>
    </div>
}

@code {
    private RecipeSubmission Submission { get; set; } = new();
    private bool Submitted { get; set; }

    private void HandleSubmit()
    {
        if (!string.IsNullOrWhiteSpace(Submission.Title) && !string.IsNullOrWhiteSpace(Submission.Category))
        {
            RecipeService.AddRecipe(Submission);
            Submitted = true;
        }
    }

    private void Reset()
    {
        Submission = new RecipeSubmission();
        Submitted = false;
    }
}

